// Facts derived from corrected/withdrawn facts are suppressed; retained raw-source edges are different.
let changed = true
while (changed) {
  changed = false
  for (const row of database
    .prepare(
      "SELECT node_id,source_id,source_type FROM memory_dependencies WHERE node_type='memory'"
    )
    .all()) {
    if (
      row.source_type === 'memory' &&
      memories.has(at(row.source_id)) &&
      !memories.has(at(row.node_id))
    ) {
      memories.add(at(row.node_id))
      changed = true
    }
  }
}
